(function(){
'use strict';
const C=window.RWCore,$=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let dataPromise,D,p,selected,history=[],cursor=-1,previewFile='unit.ini',saving,workspace,blockMode,blockTarget,blockDefsReady=false;
const storageKey='rwlab-unit-project-v1';
const btn=(text,action,cls='btn-plain',attrs='')=>`<button type="button" class="btn btn-small ${cls}" data-ed="${action}" ${attrs}>${text}</button>`;
const note=message=>typeof toast==='function'?toast(message):console.info(message);
function readLocal(){try{return C.importProject(JSON.parse(localStorage.getItem(storageKey)))}catch{return C.starter();}}
async function data(){if(!dataPromise)dataPromise=Promise.all(['editor-schema','unit_fields','logic_functions','mini_languages','mutable_stats','map_properties','dynamic_key_patterns','builtin_names'].map(f=>fetch('reference/'+f+'.json').then(r=>{if(!r.ok)throw Error('资料加载失败：'+f);return r.json()}))).then(([schema,fields,functions,mini,stats,map,dynamic,builtins])=>{RWI18n.localize({schema,fields,functions,mini,stats,map,dynamic,builtins});C.configure(schema,fields);window.RWEditorStats=stats.map(x=>x.key);return D={schema,fields,functions,mini,stats,map,dynamic,builtins};}).catch(e=>{dataPromise=null;throw e;});return dataPromise;}
function persist(){clearTimeout(saving);saving=setTimeout(()=>{try{localStorage.setItem(storageKey,JSON.stringify(p));const el=$('#ed-save-state');if(el)el.textContent='已自动保存';}catch{const el=$('#ed-save-state');if(el)el.textContent='浏览器存储空间不足，请导出项目备份';}},200);}
function record(){const s=JSON.stringify(p);if(history[cursor]!==s){history=history.slice(0,cursor+1);history.push(s);if(history.length>45)history.shift();cursor=history.length-1;}const undo=$('[data-ed=undo]'),redo=$('[data-ed=redo]');if(undo)undo.disabled=cursor<=0;if(redo)redo.disabled=cursor>=history.length-1;persist();}
function change(fn,render=true){fn();record();if(render)renderUnit();else updateOutput();}
function active(){return p.modules.find(m=>m.id===selected)||p.modules[0];}
function title(m){return C.definition(m.type)?.label||'自定义模块';}
function saveBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function saveText(text,name,type='text/plain;charset=utf-8'){saveBlob(new Blob([text],{type}),name);}
async function mount(page){dispose();$('#main').innerHTML='<div class="section-wrap"><div class="loader">正在打开编辑器…</div></div>';try{await data();if(!['editors','unit-editor','map-editor'].includes(location.hash.slice(1).split('/')[0]))return;if(page==='editors')hub();else if(page==='map-editor')window.RWMap.mount(D);else{p=p||readLocal();if(!history.length)record();selected=selected||p.modules[0]?.id;renderUnit();}}catch(e){$('#main').innerHTML=`<div class="section-wrap"><h1>编辑器暂时无法打开</h1><p>${E(e.message)}</p><a class="btn btn-dark" href="#editors">重新打开编辑器</a></div>`;}}
function dispose(){if(workspace){workspace.dispose();workspace=null;}document.querySelectorAll('.ed-dialog,.ed-block-backdrop').forEach(x=>x.remove());window.RWMap?.dispose?.();}
function hub(){const en=RWI18n.lang==='en',cards=[["unit-editor","▰","UNIT MOD","单位模组编辑器","Unit mod editor","属性、武器和动作积木，在一个工作台里完成","Build properties, weapons and action logic in one place","unit"],["map-editor","⌖","MAP EVENTS","地图与触发器","Map triggers","设置增援、目标和触发区域，保留原有地图图层","Set reinforcements, objectives and trigger regions","map"],["unit-art","✎","UNIT PIXELS","单位图片编辑器","Unit image editor","像素画、图层和动画帧，导出透明 PNG 与帧图","Pixel art, layers and animation, export PNGs and sprite sheets","art"],["map-art","▦","TERRAIN TILES","地图图片编辑器","Map image editor","绘制地块、拼接地图，检查接缝并导出地图图片","Draw tiles, arrange maps and check seamless edges","art"],["ai-art","✦","FREE CLOUD ART","AI 图形编辑器","AI art studio","用文字描述铁锈风格素材，生成后继续手工修整","Describe an RTS asset, generate a draft and refine it","ai"],["ai-help","?","MODDING ASSISTANT","模组帮助 AI","Modding assistant","结合手册和课程，解释报错、思路与代码写法","Ask about errors, ideas and code with reference context","unit"]];$('#main').innerHTML=`<div class="section-wrap ed-hub"><div class="eyebrow">RUSTED WARFARE / CREATE YOUR BATTLEFIELD</div><h1>${en?'Build your next battlefield':'把想法做成自己的模组'}</h1><p class="ed-lead">${en?'Code, sprites, maps and free cloud AI, choose a workbench and start creating':'代码、贴图、地图与免费云端 AI，选一个工作台开始创作'}</p><div class="ed-hub-grid">${cards.map(c=>' <a class="ed-hub-card '+c[7]+'" href="#'+c[0]+'"><span class="ed-tool-symbol">'+c[1]+'</span><span class="eyebrow">'+c[2]+'</span><h2>'+c[en?4:3]+' <span>↗</span></h2><p>'+c[en?6:5]+'</p><strong>'+(en?'Open workbench →':'进入工作台 →')+'</strong></a>').join('')}</div><div class="ed-hub-note"><strong>${en?'Learn by making':'边学边做，从一个完整项目开始'}</strong><p>${en?'18 new chapters across three levels, with six downloadable mod projects':'新手、进阶、终极三个阶段，18 章实作课程与 6 个配套模组项目'}</p><a href="#tutorials">${en?'Browse courses →':'查看课程 →'}</a></div></div>`; }
function editorHeader(kind){return `<div class="ed-top"><div><a class="ed-back" href="#editors">← 创作工具</a><div class="ed-editor-title"><span class="ed-status-dot"></span><h1>${kind==='unit'?'单位模组编辑器':'地图与触发器'}</h1><span class="ed-version">1.15</span></div></div><div class="ed-mode"><a href="#unit-editor" class="${kind==='unit'?'active':''}">▰ 单位模组</a><a href="#map-editor" class="${kind==='map'?'active':''}">⌖ 地图触发器</a></div></div>`;}
function renderUnit(){if(!$('#main')||!location.hash.startsWith('#unit-editor'))return;const m=active();selected=m.id;const defs=D.schema.modules;$('#main').innerHTML=`<div class="ed-shell">${editorHeader('unit')}<div class="ed-toolbar"><label class="ed-project-name"><span>项目</span><input id="ed-project-title" value="${E(p.title)}" aria-label="项目名称"></label><div class="ed-toolbar-actions">${btn('撤销','undo','',''+(cursor<=0?'disabled':''))}${btn('重做','redo','',''+(cursor>=history.length-1?'disabled':''))}${btn('导入','import')}${btn('导出项目','project')}${btn('导出 .rwmod ↓','archive','btn-dark')}<a class="btn btn-small btn-plain" href="#settings">⚙</a></div><span id="ed-save-state">已自动保存</span></div><div class="ed-layout"><aside class="ed-sidebar"><div class="ed-panel-title"><strong>模块 <span>${p.modules.length}</span></strong>${btn('＋ 新增','add-module')}</div><div class="ed-module-list">${p.modules.map(x=>`<button class="ed-module ${x.id===selected?'active':''} ${x.generated?'generated':''}" data-ed="select" data-id="${E(x.id)}"><span class="ed-module-symbol">${({core:'▰',graphics:'▧',attack:'⌖',movement:'➜',hiddenAction:'◆',action:'▶',turret:'⊕',projectile:'↗',mod:'≡'})[x.type]||'◇'}</span><span><strong>${E(title(x))}${C.definition(x.type)?.base?'<i>基础</i>':''}</strong><small>${E(C.section(x))}</small></span>${x.generated?'<span title="积木流程生成">⌘</span>':''}</button>`).join('')}</div><div class="ed-sidebar-bottom">${btn('▧ 素材与贴图','assets')}${btn('打开侦察车示例','scout')}${btn('新建单位','new')}<p>完成后点击“导出模组”，<br>即可获得游戏使用的 .rwmod 文件。</p></div></aside><section class="ed-form-panel"><div class="ed-module-heading"><div><div class="eyebrow">${E(C.section(m))}</div><h2>${E(title(m))}${m.name?' <span>/ '+E(m.name)+'</span>':''}</h2></div><div>${!C.definition(m.type)?.singleton?btn('重命名','rename'):''}${!C.definition(m.type)?.base?btn('移除','delete-module'):''}</div></div>${m.generated?'<div class="ed-inline-note">这部分代码由积木生成。请在所属动作的积木工作台中修改流程。</div>':''}<div class="ed-form-tools">${btn('＋ 添加设置项','add-field','btn-dark')}${['action','hiddenAction'].includes(m.type)?btn('⌘ 动作积木','workflow','btn-orange'):''}${m.type==='animation'?btn('＋ 动画关键帧','add-frame'):''}${btn('编辑器教程','guide')}${btn('代码编辑','raw')}${btn('这个模块有什么用？','module-help')}</div><div class="ed-field-list">${m.fields.map((f,i)=>fieldHTML(m,f,i)).join('')||'<div class="ed-empty">模块已创建，点击“添加设置项”选择中文字段。</div>'}</div><button class="ed-add-field" data-ed="add-field">＋ 添加更多设置项</button></section><aside class="ed-output"><div class="ed-panel-title"><strong>生成的代码</strong><div>${btn('复制','copy')}${btn('下载','ini')}</div></div><div class="ed-file-tabs"><button data-ed="file" data-file="unit.ini" class="${previewFile==='unit.ini'?'active':''}">单位 .ini</button><button data-ed="file" data-file="mod-info.txt" class="${previewFile==='mod-info.txt'?'active':''}">mod-info.txt</button></div><pre id="ed-code" tabindex="0"></pre><div class="ed-checks"><div class="ed-panel-title"><strong>代码检查</strong><span id="ed-check-count"></span></div><div id="ed-check-list"></div><p class="ed-check-foot">这里会检查常见的代码和引用问题。导出后，请在游戏里确认效果。</p></div></aside></div><div class="ed-bottom-note"><span>● 浏览器本地编辑</span><span>选功能，自动生成代码</span><a href="#manual">完整手册 ↗</a><span>游戏图标 © Corroding Games</span></div></div>`;updateOutput();}
function fieldHTML(m,f,i){const def=C.lookup(m,f.key),label=(RWI18n.lang==='en'?def?.label_en:RWEditorCopy.labels[f.key])||def?.description_zh?.split(/[；，]/)[0]||f.comment||'自定义命令',a=`data-field="${i}"`,opts=def?.allowed_values;let input;if(def?.type==='bool')input=`<select ${a} aria-label="${E(label)}"><option value="true" ${f.value==='true'?'selected':''}>是 / true</option><option value="false" ${f.value==='false'?'selected':''}>否 / false</option>${!['true','false'].includes(f.value)?`<option selected>${E(f.value)}</option>`:''}</select>`;else if(opts?.length&&def.type==='枚举/限定值')input=`<select ${a} aria-label="${E(label)}">${[...new Set([f.value,...opts])].map(v=>`<option value="${E(v)}" ${v===f.value?'selected':''}>${E(v)}</option>`).join('')}</select>`;else input=`<textarea ${a} aria-label="${E(label)}" spellcheck="false" rows="${f.value.includes('\n')?4:1}">${E(f.value)}</textarea>`;const expr=/表达式/.test(def?.type||'');const builder=builderKind(f.key,def);return `<article class="ed-field"><div class="ed-field-header"><label for="ed-f-${i}">${E(label)}</label><button class="ed-remove" data-ed="remove-field" data-index="${i}" aria-label="移除 ${E(f.key)}">×</button></div><div class="ed-field-meta"><code>${E(f.key)}</code><span>${E(RWI18n.lang==='en'?englishType(def,f.key):friendlyType(def?.type,f.key))}</span></div>${input.replace(a,a+` id="ed-f-${i}"`)}<div class="ed-field-tools">${expr?btn('⌘ 表达式积木','expression','btn-plain',`data-index="${i}"`):''}${builder?btn('分项填写','builder','btn-plain',`data-index="${i}" data-kind="${builder}"`):''}${btn('说明','field-help','btn-plain',`data-index="${i}"`)}</div></article>`;}
function updateOutput(){const code=$('#ed-code');if(!code)return;code.textContent=C.serialize(p,previewFile);const issues=C.validate(p),errors=issues.filter(x=>x.level==='error');$('#ed-check-count').textContent=errors.length?errors.length+' 个错误':issues.filter(x=>x.level==='warning').length+' 个提示';$('#ed-check-count').className=errors.length?'ed-red':'ed-green';$('#ed-check-list').innerHTML=issues.length?issues.slice(0,35).map(x=>`<button class="ed-issue ${x.level}" data-ed="select" data-id="${E(x.moduleId||selected)}"><b>${x.level==='error'?'!':x.level==='warning'?'△':'i'}</b>${E(x.message)}</button>`).join(''):'<p class="ed-ok">✓ 暂未发现常见问题</p>';}
function dialog(title,body,actions='',wide=false,modal=true){if(workspace){workspace.dispose();workspace=null;}$('#ed-block-backdrop')?.remove();$('#ed-dialog')?.remove();const el=document.createElement('dialog');el.id='ed-dialog';el.className='ed-dialog'+(wide?' ed-wide':'');el.innerHTML=`<div class="ed-dialog-head"><div><span class="eyebrow">RUSTED WARFARE WORKBENCH</span><h2>${E(title)}</h2></div><button class="icon-btn" data-ed="close" aria-label="关闭对话框">×</button></div><div class="ed-dialog-body">${body}</div>${actions?`<div class="ed-dialog-actions">${actions}</div>`:''}`;document.body.append(el);if(modal)el.showModal();else{el.classList.add('ed-block-mode');const backdrop=document.createElement('div');backdrop.className='ed-block-backdrop';backdrop.id='ed-block-backdrop';document.body.append(backdrop);el.show();}el.addEventListener('close',()=>{$('#ed-block-backdrop')?.remove();if(workspace){workspace.dispose();workspace=null;}el.remove();});return el;}
function addModuleDialog(){dialog('添加模块',`<label>选择模块<select id="ed-module-type">${D.schema.modules.map(d=>`<option value="${d.id}" ${d.singleton&&p.modules.some(m=>m.type===d.id)?'disabled':''}>${E(d.label)} · ${E(d.pattern)}${d.base?'（基础模块）':''}</option>`).join('')}<option value="custom">自定义模块 · 自己编写代码</option></select></label><label id="ed-module-name-label">模块名称<input id="ed-module-name" value="custom1" placeholder="例如：repair、shell"></label><label>模板<select id="ed-template"></select></label><p class="ed-inline-note" id="ed-template-note"></p><pre class="ed-template-preview" id="ed-template-preview"></pre>`,btn('创建模块','create-module','btn-dark'));refreshModuleTemplates();}
function refreshModuleTemplates(){const type=$('#ed-module-type').value,d=C.definition(type);$('#ed-module-name-label').hidden=!!d?.singleton;$('#ed-module-name').value=d?.numericName?'1':type==='custom'?'custom_section':'custom1';$('#ed-template').innerHTML='<option value="">空白模板 · 自己添加功能</option>'+D.schema.templates.filter(t=>t.module===type).map(t=>`<option value="${t.id}">${E(t.label)}</option>`).join('');const preferred=D.schema.templates.find(t=>t.module===type);if(preferred)$('#ed-template').value=preferred.id;refreshTemplate();}
function refreshTemplate(){const t=D.schema.templates.find(t=>t.id===$('#ed-template').value);$('#ed-template-note').textContent=t?(t.note||'可在创建后继续修改参数。')+(t.requirements?' 这个模板还需要：'+t.requirements.join('；'):''):'先创建模块，再添加需要的设置项。';$('#ed-template-preview').textContent=t?Object.entries(t.fields).map(([k,v])=>'# '+(D.fields.find(f=>f.key===k)?.description_zh||t.label)+'\n'+k+': '+v).join('\n'):'[所选模块]\n# 点击“添加设置项”选择字段';}
function uniqueName(type,base){let name=base,n=1;while(p.modules.some(m=>m.type===type&&m.name===name))name=base+(n++);return name;}
function memoryTemplate(t){let memory=t==='countShot'?{type:'number',name:'shots',value:'0'}:t==='toggleMode'?{type:'boolean',name:'powered',value:'false'}:null;if(!memory)return;const core=p.modules.find(m=>m.type==='core');if(!C.declaredMemory(p).some(x=>x.name===memory.name))C.set(core,'defineUnitMemory',[C.get(core,'defineUnitMemory'),memory.type+' '+memory.name].filter(Boolean).join(', '));let init=p.modules.find(m=>m.type==='hiddenAction'&&m.name==='workshopInit');if(!init){init=C.makeModule('hiddenAction','workshopInit',{autoTriggerOnEvent:'created'});p.modules.push(init);}const old=C.get(init,'setUnitMemory');if(!new RegExp('\\b'+memory.name+'\\s*=').test(old))C.set(init,'setUnitMemory',[old,memory.name+'='+memory.value].filter(Boolean).join(', '));}
function frameDialog(){dialog('新增动画关键帧',`<label>目标<select id="ed-frame-target"><option value="body">身体 / body</option><option value="leg">步足 / leg</option><option value="arm">机械臂 / arm</option><option value="turret">炮塔 / turret</option><option value="effect">特效 / effect</option></select></label><label>目标编号（身体和特效忽略）<input id="ed-frame-number" type="number" min="1" value="1"></label><label>时间<input id="ed-frame-time" value="0s" placeholder="例如：0s、0.5s、1s"></label><p class="ed-small">关键帧值会按目标筛选：身体支持缩放和帧号，步足支持位置、角度、高度和透明度，炮塔支持位置，特效支持名称与位置。</p>`,btn('创建关键帧','frame-create','btn-dark'));}
function editorGuide(){const en=RWI18n.lang==='en',steps=[["先做一个能用的单位","从默认的四个基础模块开始：设置名称、生命值、外观和移动方式。想先看看完整作品，可以点击“打开侦察车示例”。","Start with a working unit","Begin with the four required modules: set the name, health, appearance and movement. Open the scout example to explore a complete unit first."],["按需要添加模块","点击“新增”，选择炮塔、射弹或动作等模块，再选一个模板。模块名称用英文或数字填写，方便在代码中引用。","Add the modules you need","Choose Add, select a turret, projectile, action or another module, then pick a template. Use English letters or numbers for the module name so it can be referenced in code."],["用设置项完善功能","点击“添加设置项”，搜索想做的事情。每个选项旁边都有参数名，不确定怎么填时可以点击“说明”。","Choose settings by what they do","Choose Add setting and search for the feature you want. Parameter keys are shown beside their labels. Open Help if you are unsure what a value means."],["用积木编排动作","打开动作模块中的“动作积木”。把操作接到入口下面，用“如果”决定什么时候执行。可以先点击“试试条件示例”，再改成自己的效果。","Build an action with blocks","Open Action blocks in an action module. Connect operations below the starting block and use If to decide when they run. Try the condition example, then adapt it to your idea."],["保存项目，放进游戏试试","“导出项目”保存的是可继续编辑的工程；“导出模组”得到的是 .rwmod。把模组导入游戏，检查外观、攻击和动作是否符合预期。","Save your project and try it in game","Export project saves an editable project file. Export mod creates a .rwmod file for the game. Import it into Rusted Warfare and check the appearance, attacks and actions."]];dialog(en?'Your first unit, step by step':'从第一个单位开始',`<div class="ed-steps">${steps.map(x=>'<h3>'+E(x[en?2:0])+'</h3><p>'+E(x[en?3:1])+'</p>').join('')}</div><div class="ed-inline-note">${en?'Projects are saved in this browser. Export a project file regularly so you can keep a backup or continue on another device.':'进度会保存在当前浏览器。记得定期导出项目，方便备份或换个设备继续编辑。'}</div>`,'',true);}
function englishType(def,key){if(['displayText','displayDescription'].includes(key))return 'Text';const map={bool:'Switch','bool表达式':'Condition','number表达式':'Expression','unit表达式':'Unit reference',int:'Whole number',short:'Whole number',float:'Number',double:'Number','兼容字符串':'Text','内存类型声明列表':'Unit variables'};return map[def?.type]||def?.type_en||RWI18n.t(def?.type||'自定义值');}
function friendlyType(type,key){if(['displayText','displayDescription'].includes(key))return '文字';if(type==='bool')return '开关';if(type==='bool表达式')return '条件';if(type==='number表达式')return '计算式';if(type==='unit表达式')return '单位引用';if(['int','short'].includes(type))return '整数';if(['float','double'].includes(type))return '数字';if(type?.startsWith('时间'))return '时间';if(type?.startsWith('string'))return '文字';if(type==='枚举/限定值')return '选项';return type||'自定义值';}
function moduleHelp(m){const copy=RWEditorCopy.moduleHelp[m.type],en=RWI18n.lang==='en';dialog(copy?copy[en?2:0]:title(m),`<p>${E(copy?copy[en?3:1]:(en?'Add the settings your custom module needs.':'根据需要添加设置项，或直接编辑模块代码。'))}</p><p class="ed-small">${en?'Choose a template to get started, then add or adjust the settings.':'可以先选一个模板，再按需要添加或修改设置。'}</p>`);}
function localizeBlock(block){if(RWI18n.lang!=='en')return;for(const input of block.inputList){for(const field of input.fieldRow){if(field instanceof Blockly.FieldDropdown){const selectedValue=field.getValue(),options=field.getOptions(false);field.setOptions(options.map(option=>[typeof option[0]==='string'?RWI18n.t(option[0]):option[0],option[1]]));field.setValue(selectedValue);}else if(!(field instanceof Blockly.FieldTextInput)&&typeof field.getValue()==='string'){field.setValue(RWI18n.t(field.getValue()));}}}const tip=block.getTooltip();if(tip)block.setTooltip(RWI18n.t(tip));}
let fieldPage=0;
function fieldDialog(){fieldPage=0;dialog('添加设置项',`<div class="ed-search-row"><input id="ed-field-search" type="search" placeholder="搜索功能或参数名，例如：可见、伤害、isVisible" aria-label="搜索设置项"><select id="ed-field-scope" aria-label="命令筛选"><option value="module">当前模块的设置</option><option value="all">全部设置（984 项）</option></select></div><p class="ed-small" id="ed-field-count"></p><div class="ed-command-catalog" id="ed-field-results"></div><div class="ed-pager">${btn('上一页','field-prev')}<span id="ed-field-page"></span>${btn('下一页','field-next')}</div><details class="ed-custom-command"><summary>找不到需要的设置？手动添加</summary><p>熟悉代码后，可以在这里填写自定义参数、变量或动画关键帧。</p><label>命令名称<input id="ed-custom-key" placeholder="例如：@define damage"></label><label>说明<input id="ed-custom-comment" placeholder="例如：基础伤害常量"></label><label>值<input id="ed-custom-value" placeholder="18"></label>${btn('添加自定义命令','custom-field','btn-dark')}<a href="#reference" target="_blank">动态键完整参考 ↗</a></details>`,'',true);renderFieldCatalog();}
function renderFieldCatalog(){const m=active(),all=$('#ed-field-scope').value==='all',q=$('#ed-field-search').value.trim().toLowerCase();const list=(all?D.fields:C.moduleFields(m)).filter(f=>[f.key,f.description_zh,f.type,f.section].join(' ').toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(list.length/35));fieldPage=Math.max(0,Math.min(fieldPage,pages-1));$('#ed-field-count').textContent=`找到 ${list.length} 项 · ${all?'全部模块':title(m)}`;$('#ed-field-page').textContent=(fieldPage+1)+' / '+pages;$('#ed-field-results').innerHTML=list.slice(fieldPage*35,(fieldPage+1)*35).map(f=>{const index=D.fields.indexOf(f),added=m.fields.some(x=>x.key===f.key),valid=C.moduleFields(m).includes(f);return `<button data-ed="choose-field" data-index="${index}" class="ed-command-choice" ${added||!valid?'disabled':''}><strong>${E(f.description_zh)}</strong><span><code>${E(f.key)}</code><small>${E(f.type)}${all?' · '+E(f.section):''}</small></span><i>${added?'已添加':valid?'＋':'请先切换对应模块'}</i></button>`;}).join('')||'<p class="ed-empty">没有找到命令，可以使用下方手写命令。</p>';}
function defaultValue(f){if(f.asset_example?.value)return f.asset_example.value;if(f.allowed_values?.length)return f.allowed_values[0];if(f.type==='bool')return 'false';if(['int','float','short','double'].includes(f.type))return '0';if(f.type==='bool表达式')return 'true';if(f.type==='number表达式')return '0';return '';}
function helpField(index){const f=active().fields[index],def=C.lookup(active(),f.key);dialog(f.key,`<p>${E(def?.description_zh||f.comment||'自定义字段')}</p><dl class="ed-help"><dt>字段类型</dt><dd>${E(def?.type||'手写代码')}</dd><dt>缺省行为</dt><dd>${E(RWI18n.lang==='en'?'See the original reference for game defaults.':def?.default_behavior_zh||'未填写时，使用游戏的默认设置')}</dd><dt>补充说明</dt><dd>${E(RWI18n.lang==='en'?'Keep parameter keys unchanged when editing code.':def?.note_zh||'可以使用模板中的值，再按需要调整。')}</dd></dl>${def?.asset_example?'<pre class="ed-template-preview">'+E(f.key+': '+def.asset_example.value)+'</pre>':''}<details><summary>完整手册条目与来源</summary><pre class="ed-template-preview">${E(JSON.stringify(def||f,null,2))}</pre></details>`);}
function builderKind(key,def){if(['setUnitMemory','sendMessageWithData','setUnitStats','defineUnitMemory','autoTriggerOnEvent'].includes(key))return key;if(/单位生成列表/.test(def?.type||''))return 'spawnUnits';if(/射弹生成列表/.test(def?.type||''))return 'spawnProjectiles';if(/资源价格列表|动态资源赋值/.test(def?.type||''))return 'price';if(/图像堆叠列表/.test(def?.type||''))return 'imageStack';if(/^(body_|leg\d+_|arm\d+_|turret\d+_|effect_)/.test(key))return 'animationKeyframe';return '';}
let builderState;
function openBuilder(index,kind){const f=active().fields[index];builderState={index,kind};if(kind==='defineUnitMemory'){dialog('添加单位变量',`<p class="ed-small">变量用来记住次数或状态，例如开火次数、是否开启护盾。可以在单位出生时设置初始值。</p><div id="ed-build-rows">${C.splitTop(f.value).map(s=>s.trim()).filter(Boolean).map(s=>{const [type,name]=s.split(/\s+/);return memoryRow(type,name)}).join('')}</div>${btn('＋ 内存变量','builder-row')}`,btn('应用内存声明','builder-apply','btn-dark'));}
 else if(['setUnitMemory','sendMessageWithData','setUnitStats'].includes(kind)){dialog('设置变量和单位属性',`<p class="ed-small">${kind==='setUnitStats'?'选择一个属性，再决定要设置、增加还是减少它的值。':'填写变量的新值，例如 memory.shots+1。'} 也可以填写计算式或条件。</p><div id="ed-build-rows">${C.splitTop(f.value).map(s=>s.trim()).filter(Boolean).map(s=>{const a=s.match(/^(.*?)\s*(\+=|-=|=)\s*(.*)$/);return assignRow(a?.[1]||'',a?.[2]||'=',a?.[3]||s,kind)}).join('')}</div>${btn('＋ 赋值','builder-row')}`,btn('应用赋值','builder-apply','btn-dark'));}
 else if(kind==='autoTriggerOnEvent'){dialog('事件触发',`<p>选择事件；伤害、消息与队列事件可填写相应过滤条件。</p><label>事件<select id="ed-event">${D.schema.events.map(x=>`<option value="${x}" ${f.value.startsWith(x)?'selected':''}>${({"created":"出生创建","completeAndActive":"建造完成并激活","destroyed":"被摧毁","killedAnyUnit":"击杀单位","queuedUnitFinished":"排队单位完成","queueItemAdded":"加入队列","queueItemCancelled":"取消队列","teleported":"传送完成","touchTargetSuccess":"触碰目标成功","newWaypointGivenByPlayer":"玩家下达新命令","teamChanged":"所属队伍改变","transportingNewUnit":"载入乘员","transportUnloadedOrRemovedUnit":"乘员卸载或移除","tookDamage":"受到伤害","enteredTransport":"进入运输舱","leftTransport":"离开运输舱","newMessage":"收到消息","attachmentRemoved":"挂载单位移除"})[x]||x} · ${x}</option>`).join('')}</select></label><label>过滤参数<select id="ed-event-filter"><option value="">不加过滤</option></select></label><label>过滤标签<input id="ed-event-tag" placeholder="例如：fire"></label><label>原生事件列表<textarea id="ed-event-code">${E(f.value)}</textarea></label><p class="ed-small">可以保留或手写逗号分隔的多个事件。</p>`,btn('生成所选事件','event-build')+btn('应用事件列表','builder-apply','btn-dark'));refreshEvent();}
 else{const allowed=kind==='animationKeyframe'?D.schema.animationTargets[f.key.match(/^(body|leg|arm|turret|effect)/)?.[1]]:null;const mini=(D.mini[kind]||[]).filter(x=>!allowed||allowed.includes(x.key)),name=kind==='spawnUnits'?'单位生成':kind==='spawnProjectiles'?'射弹生成':kind==='price'?'资源列表':kind==='imageStack'?'图像堆叠':'动画关键帧';dialog(name+'构造器',`<p class="ed-small">选择中文参数生成片段，替换或追加到原值。复杂现有代码会原样保留在下方。</p><div class="ed-build-grid"><label>${kind==='price'?'资源名称':kind==='animationKeyframe'?'关键帧目标字段（下方选择）':'单位 / 射弹 / 图像名称'}<input id="ed-mini-name" value="${kind==='price'?'credits':kind==='animationKeyframe'?'':'tank'}"></label>${kind==='price'?'<label>资源数量<input id="ed-mini-value" value="100"></label>':''}${!['price','animationKeyframe'].includes(kind)?'<label>数量<input id="ed-mini-count" type="number" min="1" value="1"></label>':''}</div><div id="ed-mini-params"></div><div class="ed-search-row"><select id="ed-mini-key" aria-label="专用语法参数">${mini.map(x=>`<option value="${E(x.key)}">${E(x.description_zh)} · ${E(x.key)}</option>`).join('')}</select>${btn('＋ 参数','mini-param')}</div><label>生成的代码<textarea id="ed-mini-code" rows="4" spellcheck="false">${E(f.value)}</textarea></label><p id="ed-mini-preview" class="ed-inline-note"></p>`,btn('用片段替换','mini-replace')+btn('追加片段','mini-append')+btn('应用代码','builder-apply','btn-dark'),true);}
}
function memoryRow(type='number',name='counter'){return `<div class="ed-builder-row"><select data-b-type aria-label="内存类型">${D.schema.memoryTypes.map(t=>`<option ${t===type?'selected':''}>${t}</option>`).join('')}</select><input data-b-name value="${E(name)}" placeholder="变量名" aria-label="变量名"><button data-ed="remove-row" class="ed-remove" aria-label="移除变量">×</button></div>`;}
function assignRow(name='',operator='=',value='0',kind=builderState?.kind){return `<div class="ed-builder-row">${kind==='setUnitStats'?`<select data-b-name aria-label="单位属性">${D.stats.map(x=>`<option value="${x.key}" ${name===x.key?'selected':''}>${E(x.description_zh)} · ${x.key}</option>`).join('')}</select>`:`<input data-b-name value="${E(name)}" list="ed-memory-list" placeholder="变量名" aria-label="变量名"><datalist id="ed-memory-list">${C.declaredMemory(p).map(x=>`<option value="${x.name}">${x.type}</option>`).join('')}</datalist>`}<select data-b-op aria-label="赋值运算符">${(kind==='setUnitStats'?['=','+=','-=']:['=']).map(op=>`<option ${op===operator?'selected':''}>${E(op)}</option>`).join('')}</select><input data-b-value value="${E(value)}" placeholder="值或表达式" aria-label="值或表达式"><button data-ed="remove-row" class="ed-remove" aria-label="移除赋值">×</button></div>`;}
function refreshEvent(){const ev=$('#ed-event').value;$('#ed-event-filter').innerHTML='<option value="">不加过滤</option>'+(D.schema.eventFilters[ev]||[]).map(x=>`<option>${x}</option>`).join('');}
function miniFragment(){const kind=builderState.kind,name=$('#ed-mini-name').value.trim(),params=[...document.querySelectorAll('#ed-mini-params .ed-builder-row')].map(r=>r.dataset.key+(kind==='animationKeyframe'?':':'=')+r.querySelector('input').value).join(',');if(kind==='price'){const value=$('#ed-mini-value').value||'100';return [name+'='+value,...params.split(',').filter(x=>x&&!x.startsWith(name+'='))].join(', ');}if(kind==='animationKeyframe')return '{'+params+'}';const count=Number($('#ed-mini-count').value);return name+(count>1?'*'+count:'')+(params?'('+params+')':'');}
function assetDialog(){dialog('素材与贴图',`<p class="ed-small">上传自制贴图或音效，导出时放在 units/。配置中直接填写文件名。单个素材最多 4 MB，总量最多 12 MB。</p><label class="ed-upload">＋ 选择素材文件<input id="ed-assets-input" type="file" multiple accept="image/*,.ogg,.wav,.mp3"></label><div id="ed-assets-list">${p.assets.map((a,i)=>`<div class="ed-asset">${a.mime?.startsWith('image/')?`<img src="data:${E(a.mime)};base64,${a.data}" alt="${E(a.name)}">`:'<span>♫</span>'}<div><strong>${E(a.name)}</strong><small>${Math.round(a.data.length*.75/1024)} KB</small></div>${btn('移除','remove-asset','btn-plain',`data-index="${i}"`)}</div>`).join('')||'<p class="ed-empty">当前使用游戏内置调试贴图，可以换成你自己的单位图像。</p>'}</div><p class="ed-small">大项目可能超出浏览器存储容量，请导出项目 JSON 备份。</p>`);}
function rawDialog(){dialog('编辑单位代码',`<p class="ed-small">可以粘贴完整单位代码，也可以直接修改下方内容。应用后，模块列表会更新，原积木布局会清除；模组信息和素材会保留。</p><textarea id="ed-raw-code" class="ed-raw-code" spellcheck="false" rows="24">${E(C.serialize(p))}</textarea>`,btn('应用单位代码','raw-apply','btn-dark'),true);}
async function loadBlockly(){if(window.Blockly)return;for(const src of ['vendor/blockly/blockly_compressed.js','vendor/blockly/blocks_compressed.js',RWI18n.lang==='en'?'vendor/blockly/en.js':'vendor/blockly/zh-hans.js'])await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(Error('积木库加载失败，请重试'));document.head.append(s);});}
function fnParams(fn){const n=fn.names[0];if(fn.parameters_locked)return [];const special={debug:['expression'],debugPassthrough:['expression'],select:['condition','valueIfTrue','valueIfFalse'],str:['expression'],int:['value'],squareRoot:['value'],cos:['value'],sin:['value'],length:['text'],max:['a','b'],min:['a','b'], 'self.hasResources':['resources']};if(special[n])return special[n].map((name,i)=>({name,required:true,position:i,description_zh:({condition:'条件',valueIfTrue:'成立时的值',valueIfFalse:'不成立时的值',expression:'表达式',value:'数值',text:'文本',a:'数值一',b:'数值二',resources:'资源列表（原生片段）'})[name]}));return fn.parameters||[];}
function setupBlocks(){if(blockDefsReady)return;blockDefsReady=true;const B=Blockly;function def(name,init){B.Blocks[name]={init:function(){init.call(this);localizeBlock(this);}};}const out=(b,color=170)=>{b.setOutput(true);b.setColour(color);};const stmt=(b,color=30)=>{b.setPreviousStatement(true);b.setNextStatement(true);b.setColour(color);};
 def('rw_result',function(){this.appendValueInput('VALUE').appendField('结果');this.setColour(170);this.setDeletable(false);});
 def('rw_start',function(){this.appendDummyInput().appendField('当这个动作执行时');this.setNextStatement(true);this.hat='cap';this.setColour(35);this.setDeletable(false);});
 def('rw_number',function(){this.appendDummyInput().appendField(new B.FieldNumber(0),'VALUE');out(this,200);});
 def('rw_text',function(){this.appendDummyInput().appendField('文本').appendField(new B.FieldTextInput('文本'),'VALUE');out(this,150);});
 def('rw_boolean',function(){this.appendDummyInput().appendField(new B.FieldDropdown([['真','true'],['假','false']]),'VALUE');out(this,210);});
 def('rw_raw',function(){this.appendDummyInput().appendField('表达式').appendField(new B.FieldTextInput('self.hp'),'VALUE');out(this,170);this.setTooltip('填写计算式、条件或资源列表，例如 self.hp < 100。');});
 def('rw_memory',function(){this.appendDummyInput().appendField('内存').appendField(new B.FieldTextInput('counter'),'NAME');out(this,290);});
 def('rw_math',function(){this.appendValueInput('A');this.appendValueInput('B').appendField(new B.FieldDropdown([['加','+'],['减','-'],['乘','*'],['除','/'],['取余','%']]),'OP');this.setInputsInline(true);out(this,200);});
 def('rw_compare',function(){this.appendValueInput('A');this.appendValueInput('B').appendField(new B.FieldDropdown([['小于','<'],['大于','>'],['等于','=='],['不等于','!='],['不大于','<='],['不小于','>=']]),'OP');this.setInputsInline(true);out(this,210);});
 def('rw_logic',function(){this.appendValueInput('A');this.appendValueInput('B').appendField(new B.FieldDropdown([['并且','and'],['或者','or']]),'OP');this.setInputsInline(true);out(this,210);});
 def('rw_not',function(){this.appendValueInput('VALUE').appendField('不满足');out(this,210);});
 def('rw_select',function(){this.appendValueInput('COND').appendField('如果');this.appendValueInput('YES').appendField('取值');this.appendValueInput('NO').appendField('否则取值');out(this,210);});
 def('rw_if',function(){this.appendValueInput('COND').appendField('如果');this.appendStatementInput('THEN').appendField('那么');this.appendStatementInput('ELSE').appendField('否则');stmt(this,210);});
 def('rw_command',function(){const choices=D.fields.filter(f=>f.section==='action_NAME / hiddenAction_NAME'&&!['alsoTriggerAction','alsoQueueAction','alsoTriggerOrQueueActionConditional','autoTrigger','autoTriggerOnEvent'].includes(f.key)).map(f=>[(f.label_en||f.description_zh.split(/[；，]/)[0])+' · '+f.key,f.key]);this.appendDummyInput().appendField('命令').appendField(new B.FieldDropdown(choices),'KEY');this.appendValueInput('VALUE').appendField('设为');stmt(this,30);});
 def('rw_call',function(){this.appendDummyInput().appendField('调用动作').appendField(new B.FieldTextInput('repair'),'NAME');stmt(this,280);this.setTooltip('填写要调用的动作名称，例如 repair。');});
 def('rw_memory_set',function(){this.appendDummyInput().appendField('设置内存').appendField(new B.FieldTextInput('counter'),'NAME');this.appendValueInput('VALUE').appendField('为');stmt(this,290);});
 def('rw_stat_set',function(){this.appendDummyInput().appendField('修改属性').appendField(new B.FieldDropdown(D.stats.map(x=>[x.description_zh+' · '+x.key,x.key])),'NAME').appendField(new B.FieldDropdown([['设为','='],['增加','+='],['减少','-=']]),'OP');this.appendValueInput('VALUE').appendField('值');stmt(this,30);});
 D.functions.forEach((f,i)=>{if(f.names[0]==='memory'||D.schema.restrictedFunctions.includes(f.names[0]))return;def('rw_fn_'+i,function(){this.appendDummyInput().appendField((f.label_en||f.description_zh.split(/[；，]/)[0]).slice(0,42)).appendField(new B.FieldDropdown(f.names.map(n=>[n,n])),'FN');fnParams(f).forEach((param,j)=>this.appendValueInput('P'+j).appendField((param.description_zh||param.name).slice(0,19)+' · '+param.name+(param.required?' *':'（可选）')));out(this,/bool/.test(f.return_type)?210:/number/.test(f.return_type)?200:170);this.setTooltip(f.description_zh+(RWI18n.lang==='en'?'':'\n'+(f.custom_syntax||'')+'\n'+(f.parameter_usage_note||''))); });});}
function expr(block){if(!block)throw Error('有一个必填积木插槽为空。');const v=n=>expr(block.getInputTargetBlock(n)),val=n=>block.getFieldValue(n);switch(block.type){case'rw_raw':if(!val('VALUE').trim())throw Error('表达式为空');return val('VALUE');case'rw_number':return String(val('VALUE'));case'rw_text':return "'"+val('VALUE').replace(/\\/g,'\\\\').replace(/'/g,"\\'")+"'";case'rw_boolean':return val('VALUE');case'rw_memory':if(!/^[A-Za-z_]\w*$/.test(val('NAME')))throw Error('内存名称不正确');return 'memory.'+val('NAME');case'rw_math':case'rw_compare':case'rw_logic':return '('+v('A')+' '+val('OP')+' '+v('B')+')';case'rw_not':return '(not '+v('VALUE')+')';case'rw_select':return 'select('+v('COND')+', '+v('YES')+', '+v('NO')+')';}
 if(block.type.startsWith('rw_fn_')){const fn=D.functions[Number(block.type.slice(6))],params=fnParams(fn),args=[];params.forEach((param,j)=>{const child=block.getInputTargetBlock('P'+j);if(!child){if(param.required)throw Error(fn.names[0]+' 缺少 '+param.name);return;}const code=expr(child);args.push(param.position!==undefined?code:param.name+'='+code);});const name=val('FN');if(name==='self.hasResources')return name+'('+args.join(', ')+')';return name+(args.length||fn.custom_syntax?.includes('(')?'('+args.join(', ')+')':'');}
 throw Error('不支持的表达式积木：'+block.type);}
function statement(block){const nodes=[];for(let b=block;b;b=b.getNextBlock()){if(nodes.length>100)throw Error('流程过长');if(b.type==='rw_if')nodes.push({kind:'if',condition:expr(b.getInputTargetBlock('COND')),then:statement(b.getInputTargetBlock('THEN')),else:statement(b.getInputTargetBlock('ELSE'))});else if(b.type==='rw_call')nodes.push({kind:'call',name:b.getFieldValue('NAME')});else if(b.type==='rw_command')nodes.push({kind:'command',key:b.getFieldValue('KEY'),value:expr(b.getInputTargetBlock('VALUE'))});else if(b.type==='rw_memory_set')nodes.push({kind:'command',key:'setUnitMemory',value:b.getFieldValue('NAME')+'='+expr(b.getInputTargetBlock('VALUE'))});else if(b.type==='rw_stat_set')nodes.push({kind:'command',key:'setUnitStats',value:b.getFieldValue('NAME')+b.getFieldValue('OP')+expr(b.getInputTargetBlock('VALUE'))});else throw Error('不能在动作序列中使用这种积木。');}return nodes;}
function toolbox(mode){const blocks=types=>types.map(type=>({kind:'block',type})),common=['rw_number','rw_raw','rw_memory','rw_text','rw_boolean'],logic=['rw_compare','rw_logic','rw_not','rw_select'],math=['rw_math'];const cats=[];if(mode==='workflow')cats.push({kind:'category',name:'动作与条件',colour:35,contents:blocks(['rw_if','rw_command','rw_call','rw_memory_set','rw_stat_set'])});cats.push({kind:'category',name:'数值与引用',colour:170,contents:blocks(common)},{kind:'category',name:'条件与判断',colour:210,contents:blocks(logic)},{kind:'category',name:'数学运算',colour:200,contents:blocks(math)});const functions=D.functions.map((f,i)=>({f,i})).filter(({f})=>f.names[0]!=='memory'&&!D.schema.restrictedFunctions.includes(f.names[0]));for(const [label,filter]of [['单位函数',f=>f.names[0].startsWith('self.')],['游戏与事件',f=>!f.names[0].startsWith('self.')]])cats.push({kind:'category',name:label,colour:170,contents:blocks(functions.filter(({f})=>filter(f)).map(({i})=>'rw_fn_'+i))});for(const c of cats)c.name=RWI18n.t(c.name);return {kind:'categoryToolbox',contents:cats};}
async function blocksDialog(mode,index){await loadBlockly();setupBlocks();blockMode=mode;blockTarget=index;dialog(mode==='workflow'?'动作积木':'表达式积木',`<p class="ed-small">${mode==='workflow'?'从左侧拖出积木，接到“当这个动作执行时”下面。用“如果”设置条件，把要做的操作放进分支中。':'把需要的积木接到“结果”。可以比较数值、组合条件，或读取单位的变量和属性。'}</p><div class="ed-block-tools"><input id="ed-fn-search" type="search" placeholder="搜索函数中文含义或名称" aria-label="搜索逻辑函数"><select id="ed-fn-choice" aria-label="逻辑函数"></select>${btn('添加函数','insert-function')}${mode==='workflow'?btn('试试条件示例','block-example'):''}</div><div id="ed-blockly" aria-label="可视化积木编辑区"></div><div class="ed-block-result"><strong>代码预览</strong><pre id="ed-block-code"></pre></div><p class="ed-small">积木靠近接口时会提示连接位置，松开即可拼接。只有接到入口或结果的积木会写入代码。</p>`,btn('应用到模块','blocks-apply','btn-dark'),true,false);renderFunctionPicker();const theme=Blockly.Theme.defineTheme('rw-workshop',{base:Blockly.Themes.Classic,fontStyle:{family:'Arial, Microsoft YaHei, sans-serif',size:14,weight:'normal'}});workspace=Blockly.inject('ed-blockly',{theme,toolbox:toolbox(mode),renderer:'zelos',media:'vendor/blockly/media/',sounds:false,trashcan:true,scrollbars:true,move:{scrollbars:true,drag:true,wheel:true},zoom:{controls:true,wheel:true,startScale:1,minScale:.4,maxScale:1.5},grid:{spacing:24,length:2,colour:'#d9ded5',snap:true}});const saved=mode==='workflow'?p.workflows?.[selected]?.workspace:p.expressionWorkspaces?.[selected+':'+active().fields[index]?.key];if(saved){try{Blockly.serialization.workspaces.load(migrateBlockState(saved),workspace);}catch{workspace.clear();}}
 if(!workspace.getAllBlocks(false).length){const root=workspace.newBlock(mode==='workflow'?'rw_start':'rw_result');root.initSvg();root.render();root.moveBy(30,35);if(mode!=='workflow'){const raw=workspace.newBlock('rw_raw');raw.setFieldValue(active().fields[index].value||'true','VALUE');raw.initSvg();raw.render();root.getInput('VALUE').connection.connect(raw.outputConnection);}}
 workspace.addChangeListener(()=>{try{$('#ed-block-code').textContent=mode==='workflow'?workflowPreview():blockExpression();}catch(e){if($('#ed-block-code'))$('#ed-block-code').textContent=e.message;}});requestAnimationFrame(()=>{if(workspace){workspace.render();Blockly.svgResize(workspace);workspace.fireChangeListener(new Blockly.Events.FinishedLoading(workspace));}});}
function renderFunctionPicker(){const q=$('#ed-fn-search').value.toLowerCase();$('#ed-fn-choice').innerHTML=D.functions.map((f,i)=>({f,i})).filter(({f})=>f.names[0]!=='memory'&&[f.description_zh,...f.names].join(' ').toLowerCase().includes(q)).map(({f,i})=>`<option value="${i}" ${D.schema.restrictedFunctions.includes(f.names[0])?'disabled':''}>${E(f.description_zh.slice(0,35))} · ${E(f.names.join(' / '))}${f.parameters_locked?'（固定参数）':''}</option>`).join('');}
function migrateBlockState(state){const result=C.clone(state);for(const block of result.blocks?.blocks||[]){if(block.type==='rw_start'&&block.inputs?.DO){block.next=block.inputs.DO;delete block.inputs.DO;if(!Object.keys(block.inputs).length)delete block.inputs;}}return result;}
function workflowPreview(){const result=C.compileWorkflow(p,active(),blockNodes(),null);return C.serialize({...result,modules:result.modules.filter(x=>x.id===selected||x.generated===selected)});}
function blockExpression(){const roots=workspace.getBlocksByType('rw_result',false);if(roots.length!==1)throw Error('请保留一个结果积木。');return expr(roots[0].getInputTargetBlock('VALUE'));}
function blockNodes(){const roots=workspace.getBlocksByType('rw_start',false);if(roots.length!==1)throw Error('请保留一个动作入口。');return statement(roots[0].getNextBlock());}
function blockExample(){workspace.clear();const create=(t,values={})=>{const b=workspace.newBlock(t);for(const [k,v]of Object.entries(values))b.setFieldValue(v,k);b.initSvg();b.render();return b;};const root=create('rw_start'),cond=create('rw_if'),raw=create('rw_raw',{VALUE:'self.hp < self.maxHp * 0.5'}),stat=create('rw_stat_set',{NAME:'hp',OP:'='}),value=create('rw_raw',{VALUE:'self.hp + 5'});root.moveBy(30,35);root.nextConnection.connect(cond.previousConnection);cond.getInput('COND').connection.connect(raw.outputConnection);cond.getInput('THEN').connection.connect(stat.previousConnection);stat.getInput('VALUE').connection.connect(value.outputConnection);}
async function handle(b){const a=b.dataset.ed,m=active();if(a==='close')return $('#ed-dialog').close();if(a==='select'){selected=b.dataset.id;renderUnit();return;}if(a==='file'){previewFile=b.dataset.file;renderUnit();return;}if(a==='undo'||a==='redo'){cursor+=a==='undo'?-1:1;p=JSON.parse(history[cursor]);selected=p.modules.some(x=>x.id===selected)?selected:p.modules[0].id;persist();renderUnit();return;}if(a==='add-module')return addModuleDialog();if(a==='create-module'){const type=$('#ed-module-type').value,d=C.definition(type),name=d?.singleton?'':$('#ed-module-name').value.trim(),t=D.schema.templates.find(t=>t.id===$('#ed-template').value);if(!d?.singleton&&!/^[A-Za-z0-9_\-]+$/.test(name))throw Error('模块名称请使用英文、数字、下划线或连字符。');if(d?.numericName&&!/^\d+$/.test(name))throw Error('步足 / 机械臂名称必须为数字。');const mod=C.makeModule(type,name,Object.fromEntries(Object.entries(t?.fields||{}).map(([key,value])=>[key,RWI18n.t(value)])));if(p.modules.some(x=>C.section(x)===C.section(mod)))throw Error('已经存在同名模块。');$('#ed-dialog').close();change(()=>{p.modules.push(mod);selected=mod.id;memoryTemplate(t?.id);});return;}
 if(a==='rename'){dialog('重命名模块',`<label>名称后缀<input id="ed-rename" value="${E(m.name)}"></label><p class="ed-small">已有代码引用需要同步修改；代码检查会提示找不到的常用引用。</p>`,btn('应用名称','rename-apply','btn-dark'));return;}
 if(a==='rename-apply'){const name=$('#ed-rename').value.trim();if(!/^[A-Za-z0-9_\-]+$/.test(name)||C.definition(m.type)?.numericName&&!/^\d+$/.test(name))throw Error('名称格式不正确');if(p.modules.some(x=>x.id!==m.id&&x.type===m.type&&x.name===name))throw Error('名称已经存在');$('#ed-dialog').close();change(()=>m.name=name);return;}
 if(a==='delete-module'){dialog('移除此模块？',`<p>将移除 ${E(title(m))} / ${E(C.section(m))}。基础四模块会保留，删除后可撤销。</p>`,btn('移除模块','delete-confirm','btn-orange'));return;}
 if(a==='delete-confirm'){$('#ed-dialog').close();change(()=>{p.modules=p.modules.filter(x=>x.id!==m.id&&x.generated!==m.id);delete p.workflows[m.id];selected=p.modules[0].id;});return;}
 if(a==='guide')return editorGuide();if(a==='add-frame')return frameDialog();if(a==='frame-create'){const target=$('#ed-frame-target').value,number=$('#ed-frame-number').value,time=$('#ed-frame-time').value;if(!/^\d+(\.\d+)?s$/.test(time))throw Error('时间请写 0s、0.5s 等格式');if(target!=='body'&&!/^\d+$/.test(number))throw Error('目标编号必须为数字');const key=target+(target==='body'||target==='effect'?'':number)+'_'+time;if(m.fields.some(f=>f.key===key))throw Error('关键帧已存在');const value=target==='body'?'{scale:1}':target==='effect'?'{name:small}':'{x:0,y:0}';change(()=>m.fields.push(C.field(key,value,'动画关键帧')),false);$('#ed-dialog').close();renderUnit();return openBuilder(m.fields.length-1,'animationKeyframe');}if(a==='add-field')return fieldDialog();if(a==='field-prev'||a==='field-next'){fieldPage+=a==='field-next'?1:-1;renderFieldCatalog();return;}
 if(a==='choose-field'){const f=D.fields[Number(b.dataset.index)];if(/\{/.test(f.key)){dialog('填写动态命令名称',`<p>占位符需要替换成实际数字或名称。</p><label>原始命令<input id="ed-dynamic-key" value="${E(f.key.replace('{N}','1').replace('{NAME}','custom'))}"></label><p>${E(f.description_zh)}</p>`,btn('添加命令','dynamic-field','btn-dark',`data-index="${b.dataset.index}"`));return;}change(()=>m.fields.push(C.field(f.key,defaultValue(f),f.description_zh)),false);renderFieldCatalog();renderUnit();return;}
 if(a==='dynamic-field'){const f=D.fields[Number(b.dataset.index)],key=$('#ed-dynamic-key').value.trim();if(!key||/[{}\r\n:=\[\]]/.test(key)||m.fields.some(x=>x.key===key))throw Error('请填写有效且不重复的命令名');change(()=>m.fields.push(C.field(key,defaultValue(f),f.description_zh)),false);$('#ed-dialog').close();renderUnit();return;}if(a==='custom-field'){const key=$('#ed-custom-key').value.trim();if(!key||/[\r\n:=\[\]]/.test(key)||m.fields.some(f=>f.key===key))throw Error('请填写不重复的有效命令名');change(()=>m.fields.push(C.field(key,$('#ed-custom-value').value,$('#ed-custom-comment').value)),false);$('#ed-dialog').close();renderUnit();return;}
 if(a==='remove-field'){change(()=>m.fields.splice(Number(b.dataset.index),1));return;}if(a==='field-help')return helpField(Number(b.dataset.index));
 if(a==='module-help'){moduleHelp(m);return;}
 if(a==='copy'){await copy(C.serialize(p,previewFile));return;}if(a==='ini'){const files=await RWExport.files([{name:previewFile,data:C.serialize(p,previewFile)}]);if(files)saveText(files[0].data,previewFile==='unit.ini'?C.cleanName(C.get(p.modules.find(x=>x.type==='core'),'name'))+'.ini':'mod-info.txt');return;}if(a==='project'){saveText(JSON.stringify(p,null,2),String(p.title||'unit-project').replace(/[\\/:*?"<>|\u0000-\u001f]/g,'_').slice(0,70)+'.rwproject.json','application/json');return;}if(a==='archive'){if(!p.modules.some(x=>x.type==='mod'))throw Error('请先新增“模组信息”模块，再导出完整模组。');const issues=C.validate(p);if(issues.some(x=>x.level==='error')){note('请先修复代码检查中的错误，再打包 .rwmod；项目 JSON 仍可保存。');return;}const files=await RWExport.files([{name:'mod-info.txt',data:C.serialize(p,'mod-info.txt')},{name:'units/'+C.cleanName(C.get(p.modules.find(x=>x.type==='core'),'name'))+'.ini',data:C.serialize(p)},...(p.assets||[]).map(a=>({name:'units/'+a.name,data:Uint8Array.from(atob(a.data),c=>c.charCodeAt(0))}))]);if(!files)return;saveBlob(C.zip(files),C.cleanName(C.get(p.modules.find(x=>x.type==='core'),'name'))+'.rwmod');note('已打包单位配置、mod-info.txt 与上传素材');return;}
 if(a==='import'){dialog('导入单位或工坊项目',`<label class="ed-upload">选择 .ini / mod-info.txt / 项目 JSON<input id="ed-import-input" type="file" accept=".ini,.txt,.json"></label><p>INI 导入保留未知模块与命令；项目 JSON 同时保留素材和积木布局。.rwmod 请先解压，再导入其中的单位 INI。</p><label>或粘贴完整 INI<textarea id="ed-import-code" rows="10" spellcheck="false" placeholder="[core]&#10;name: myUnit"></textarea></label>`,btn('导入粘贴代码','import-paste','btn-dark'));return;}
 if(a==='import-paste'){const text=$('#ed-import-code').value;replaceINI(text);$('#ed-dialog').close();renderUnit();return;}if(a==='raw')return rawDialog();if(a==='raw-apply'){replaceINI($('#ed-raw-code').value);$('#ed-dialog').close();renderUnit();return;}
 if(a==='new'){dialog('新建单位项目',`<p>将从四个基础模块重新开始。当前项目建议先导出 JSON；此操作也可撤销。</p>`,btn('创建基础单位','new-confirm','btn-dark'));return;}if(a==='new-confirm'){$('#ed-dialog').close();change(()=>{p=C.starter();selected=p.modules[0].id;});return;}
 if(a==='scout-confirm'){$('#ed-dialog')?.close();const r=await fetch('downloads/examples/Annotated_Scout/units/scout.ini');if(!r.ok)throw Error('示例下载失败');replaceINI(await r.text());p.title='手册示例 · 侦察车';record();renderUnit();note('已载入完整说明侦察车，可使用撤销恢复');return;}
 if(a==='scout'){dialog('打开侦察车示例',`<p>将替换当前单位代码，保留模组信息与素材。这个示例包含双弹种、射击计数和切换动作，可用于对照学习；可撤销恢复当前单位。</p>`,btn('载入示例','scout-confirm','btn-dark'));return;}if(a==='assets')return assetDialog();if(a==='remove-asset'){change(()=>p.assets.splice(Number(b.dataset.index),1),false);assetDialog();return;}
 if(a==='expression')return blocksDialog('expression',Number(b.dataset.index));if(a==='workflow')return blocksDialog('workflow');if(a==='insert-function'){const value=$('#ed-fn-choice').value;if(value==='')return;const block=workspace.newBlock('rw_fn_'+value);block.initSvg();block.render();const r=workspace.getMetrics();block.moveBy((r?.viewLeft||0)+120,(r?.viewTop||0)+180);block.select();return;}if(a==='block-example')return blockExample();
 if(a==='blocks-apply'){const state=Blockly.serialization.workspaces.save(workspace);if(blockMode==='workflow'){const nodes=blockNodes(),result=C.compileWorkflow(p,m,nodes,state);change(()=>p=result,false);}else{const code=blockExpression();change(()=>{m.fields[blockTarget].value=code;(p.expressionWorkspaces||={})[m.id+':'+m.fields[blockTarget].key]=state;},false);}$('#ed-dialog').close();renderUnit();note('积木已转换为原生 INI');return;}
 if(a==='builder')return openBuilder(Number(b.dataset.index),b.dataset.kind);if(a==='builder-row'){$('#ed-build-rows').insertAdjacentHTML('beforeend',builderState.kind==='defineUnitMemory'?memoryRow():assignRow());return;}if(a==='remove-row'){b.closest('.ed-builder-row').remove();return;}if(a==='event-build'){const filter=$('#ed-event-filter').value,tag=$('#ed-event-tag').value.trim();$('#ed-event-code').value=$('#ed-event').value+(filter&&tag?'('+filter+"='"+tag.replace(/'/g,'')+"')":'');return;}
 if(a==='mini-param'){const key=$('#ed-mini-key').value,def=D.mini[builderState.kind].find(x=>x.key===key);const r=document.createElement('div');r.className='ed-builder-row';r.dataset.key=key;r.innerHTML=`<label>${E(def.description_zh)}<small>${E(key)} · ${E(def.type)}</small></label><input value="${def.type==='bool'?'true':'0'}" aria-label="${E(def.description_zh)}"><button data-ed="remove-row" class="ed-remove" aria-label="移除参数">×</button>`;$('#ed-mini-params').append(r);return;}
 if(a==='mini-replace'||a==='mini-append'){const fragment=miniFragment();$('#ed-mini-code').value=a==='mini-replace'?fragment:[$('#ed-mini-code').value,fragment].filter(Boolean).join(', ');$('#ed-mini-preview').textContent='已生成：'+fragment;return;}
 if(a==='builder-apply'){let value;const kind=builderState.kind;if(kind==='defineUnitMemory'){value=[...document.querySelectorAll('#ed-build-rows .ed-builder-row')].map(r=>{const name=r.querySelector('[data-b-name]').value.trim();if(!/^[A-Za-z_]\w*$/.test(name))throw Error('变量名请使用英文、数字或下划线，并以英文或下划线开头');return r.querySelector('[data-b-type]').value+' '+name;}).join(', ');}else if(['setUnitMemory','sendMessageWithData','setUnitStats'].includes(kind))value=[...document.querySelectorAll('#ed-build-rows .ed-builder-row')].map(r=>{const name=r.querySelector('[data-b-name]').value.trim();if(!/^[A-Za-z_]\w*$/.test(name))throw Error('变量或属性名称不正确');return name+r.querySelector('[data-b-op]').value+r.querySelector('[data-b-value]').value;}).join(', ');else value=kind==='autoTriggerOnEvent'?$('#ed-event-code').value:$('#ed-mini-code').value;change(()=>m.fields[builderState.index].value=value,false);$('#ed-dialog').close();renderUnit();return;}
}
function replaceINI(text){const modules=C.parseINI(text),isInfo=modules.every(m=>['mod','music'].includes(m.type));change(()=>{p.modules=[...p.modules.filter(m=>isInfo?!['mod','music'].includes(m.type):['mod','music'].includes(m.type)),...modules];p.workflows={};p.expressionWorkspaces={};selected=modules[0].id;},false);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ed]');if(!b)return;if(!p)return;Promise.resolve(handle(b)).catch(e=>note(e.message||'操作失败'));});
document.addEventListener('input',e=>{if(e.target.id==='ed-field-search'){fieldPage=0;renderFieldCatalog();}if(e.target.id==='ed-fn-search')renderFunctionPicker();if(e.target.matches('[data-field]')){active().fields[Number(e.target.dataset.field)].value=e.target.value;persist();updateOutput();}});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.matches('[data-field]'))record();if(el.id==='ed-project-title')change(()=>p.title=el.value,false);if(el.id==='ed-module-type')refreshModuleTemplates();if(el.id==='ed-template')refreshTemplate();if(el.id==='ed-field-scope'){fieldPage=0;renderFieldCatalog();}if(el.id==='ed-event')refreshEvent();if(el.id==='ed-import-input'){const file=el.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('项目超过 20 MB，请减少素材后导入。');const text=await file.text();if(file.name.endsWith('.json'))change(()=>{p=C.importProject(text);selected=p.modules[0].id;},false);else replaceINI(text);$('#ed-dialog').close();renderUnit();note('已导入，可撤销恢复原项目');}if(el.id==='ed-assets-input'){let total=p.assets.reduce((n,a)=>n+a.data.length*.75,0);for(const f of el.files){if(!/^[A-Za-z0-9_.\-]+$/.test(f.name))throw Error('素材文件名请先改为英文、数字、下划线或连字符。');if(f.size>4*1024*1024||total+f.size>12*1024*1024)throw Error('素材超过大小限制，请压缩后上传。');if(!/^image\//.test(f.type)&&! /\.(ogg|wav|mp3)$/i.test(f.name))throw Error('请选择图片或音效文件');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f);});total+=f.size;p.assets=p.assets.filter(a=>a.name!==f.name);p.assets.push({name:f.name,mime:f.type||'application/octet-stream',data});}record();assetDialog();}}catch(e){note(e.message);}});
window.addEventListener('rw-before-language-change',event=>{if(p){clearTimeout(saving);try{localStorage.setItem(storageKey,JSON.stringify(p))}catch{event.preventDefault();note('项目较大，请先导出项目备份，再切换语言。');}}});
window.RWEditor={mount,dispose,editorHeader,data,async addAsset(asset){await data();p=p||readLocal();p.assets=p.assets.filter(a=>a.name!==asset.name);p.assets.push(asset);record();if(location.hash==='#unit-editor')renderUnit();},async currentCode(){await data();p=p||readLocal();return C.serialize(p);}};
})();
